"""Runs student model code generated by the blocks.

Generated code looks like this, and imports its helpers from this module:

    from torch import nn
    from harness import load_data, train, evaluate, decode_practice

    train_data, val_data = load_data()
    model = nn.Sequential(nn.Flatten(), nn.LazyLinear(36))
    train(model, train_data, val_data, epochs=5)
    evaluate(model, val_data)
    decode_practice(model)

Run student code (the server does this in a subprocess):

    python shared/harness.py CODE.py --run-dir DIR [--seed N] [--threads N]

Progress goes to stdout as lines of "@@" + JSON, mixed with anything the student prints.
The run dir gets model.pt (trained weights) and practice_pred.npy (decoded grid).

The grader calls load_trained_model(), which re-runs the same code but loads saved
weights instead of training.
"""

import argparse
import json
import os
import sys
import time
import traceback
from pathlib import Path

import numpy as np
import torch
from torch import nn
from torch.utils.data import DataLoader, TensorDataset

REPO = Path(__file__).resolve().parent.parent
if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from shared import config, workspaces  # noqa: E402
from shared.palette import CLASSES  # noqa: E402

DATA_DIR = Path(os.environ.get("MPNN_DATA", REPO / "data" / "processed" / "public"))
WORKSPACE = workspaces.current()
TRAIN_PER_CLASS = int(os.environ.get("MPNN_TRAIN_PER_CLASS", config.TRAIN_PER_CLASS))
EVAL_BATCH = 1024
STEP_EVENTS_PER_EPOCH = 40
VAL_EVENTS_PER_EPOCH = 4

# mode is "run" (train for real) or "load" (grader: load saved weights, skip training)
_state = {"mode": "run", "run_dir": Path("run"), "weights": None, "model": None}


class StudentError(Exception):
    """A mistake in the student's blocks, explained in plain language."""


def emit(event: str, **data):
    print("@@" + json.dumps({"event": event, **data}), flush=True)


# ---------- functions called by generated code ----------

def load_data():
    """Return (train_data, val_data) as TensorDatasets of (1, 28, 28) images and labels."""
    if _state["mode"] == "load":
        return None, None
    train = np.load(DATA_DIR / "train.npz")
    val = np.load(DATA_DIR / "val.npz")
    keep = np.concatenate([np.flatnonzero(train["y"] == c)[:TRAIN_PER_CLASS]
                           for c in range(config.NUM_CLASSES)])
    keep.sort()  # the pool is already shuffled; sorting keeps that order
    train_data = _to_dataset(train["x"][keep], train["y"][keep])
    val_data = _to_dataset(val["x"], val["y"])
    emit("data", train=len(train_data), val=len(val_data), classes=CLASSES)
    return train_data, val_data


def train(model, train_data, val_data, epochs=WORKSPACE.default_epochs):
    """Train with fixed settings (Adam, fixed learning rate and batch size)."""
    if not isinstance(epochs, int) or not 1 <= epochs <= WORKSPACE.max_epochs:
        raise StudentError(f"Epochs must be a whole number from 1 to {WORKSPACE.max_epochs}.")
    check_model(model)
    _state["model"] = model

    if _state["mode"] == "load":
        model.load_state_dict(torch.load(_state["weights"], weights_only=True))
        model.eval()
        return

    emit("model", layers=describe_layers(model))
    optimizer = torch.optim.Adam(model.parameters(), lr=config.LEARNING_RATE)
    loss_fn = nn.CrossEntropyLoss()
    loader = DataLoader(train_data, batch_size=config.BATCH_SIZE, shuffle=True)
    steps_per_epoch = len(loader)
    step_every = max(1, steps_per_epoch // STEP_EVENTS_PER_EPOCH)
    val_steps = {round(k * steps_per_epoch / VAL_EVENTS_PER_EPOCH) for k in range(1, VAL_EVENTS_PER_EPOCH + 1)}

    emit("train_start", epochs=epochs, steps_per_epoch=steps_per_epoch,
         parameters=sum(p.numel() for p in model.parameters()))
    start = time.perf_counter()
    for epoch in range(epochs):
        running, count = 0.0, 0
        for i, (x, y) in enumerate(loader, start=1):
            model.train()
            loss = loss_fn(model(x), y)
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()
            running += loss.item()
            count += 1
            progress = epoch + i / steps_per_epoch
            if i % step_every == 0:
                emit("step", progress=round(progress, 4), loss=round(running / count, 4))
                running, count = 0.0, 0
            if i in val_steps:
                emit("val", progress=round(progress, 4), accuracy=round(accuracy(model, val_data), 4))
        emit("epoch", epoch=epoch + 1, seconds=round(time.perf_counter() - start, 2))

    torch.save(model.state_dict(), _state["run_dir"] / "model.pt")
    emit("train_done", seconds=round(time.perf_counter() - start, 2))


def evaluate(model, val_data):
    """Report accuracy on the validation set."""
    if _state["mode"] == "load":
        return
    acc = accuracy(model, val_data)
    emit("evaluate", accuracy=round(acc, 4))
    return acc


def decode_practice(model):
    """Classify every practice character and report the decoded grid of classes."""
    pred = predict_practice(model)
    if _state["mode"] == "load":
        return pred
    np.save(_state["run_dir"] / "practice_pred.npy", pred)
    emit("decoded", grid=pred.tolist())
    return pred


# ---------- helpers ----------

def _to_dataset(x: np.ndarray, y: np.ndarray) -> TensorDataset:
    images = torch.from_numpy(x).float().div_(255).unsqueeze(1)
    return TensorDataset(images, torch.from_numpy(y).long())


def check_model(model):
    """Run one dummy image through the model and explain common mistakes."""
    if not isinstance(model, nn.Module):
        raise StudentError("The model must be built from layer blocks.")
    try:
        with torch.no_grad():
            out = model(torch.zeros(1, 1, 28, 28))
    except Exception as e:
        raise StudentError(f"The model could not process an image: {e}") from e
    if not any(True for _ in model.parameters()):
        raise StudentError("The model has no Linear layer, so it has nothing to learn. Add a Linear block.")
    if out.dim() != 2 or out.shape[1] != config.NUM_CLASSES:
        got = out.shape[1] if out.dim() == 2 else tuple(out.shape[1:])
        raise StudentError(
            f"The last layer gives {got} outputs, but there are {config.NUM_CLASSES} classes "
            f"(0-9 and A-Z). Set the last Linear block to {config.NUM_CLASSES} outputs.")


def describe_layers(model) -> list[str]:
    """Short layer names, e.g. ["Conv(16)", "ReLU", "MaxPool", "Flatten", "Linear(36)"]."""
    layers = list(model.children()) if isinstance(model, nn.Sequential) else [model]

    def name(m):
        if isinstance(m, nn.Linear):
            return f"Linear({m.out_features})"
        if isinstance(m, nn.Conv2d):
            return f"Conv({m.out_channels})"
        if isinstance(m, nn.MaxPool2d):
            return "MaxPool"
        return type(m).__name__
    return [name(m) for m in layers]


@torch.no_grad()
def predict(model, images: torch.Tensor) -> np.ndarray:
    model.eval()
    return torch.cat([model(images[i:i + EVAL_BATCH]).argmax(1)
                      for i in range(0, len(images), EVAL_BATCH)]).numpy()


def accuracy(model, data: TensorDataset) -> float:
    images, labels = data.tensors
    return float((predict(model, images) == labels.numpy()).mean())


def predict_practice(model) -> np.ndarray:
    """Predicted class for every practice character, as an (H, W) grid."""
    chars = np.load(DATA_DIR / WORKSPACE.practice_file)["x"]
    h, w = chars.shape[:2]
    images = torch.from_numpy(chars.reshape(-1, 28, 28)).float().div_(255).unsqueeze(1)
    return predict(model, images).reshape(h, w)


def _exec_student_code(code_path: Path):
    source = code_path.read_text(encoding="utf-8")
    exec(compile(source, str(code_path), "exec"), {"__name__": "__main__"})


def load_trained_model(code_path, weights_path):
    """Grader entry point: rebuild the student's model and load its saved weights."""
    sys.modules.setdefault("harness", sys.modules[__name__])
    _state.update(mode="load", weights=Path(weights_path), model=None)
    _exec_student_code(Path(code_path))
    if _state["model"] is None:
        raise StudentError("The code never calls train(), so there is no trained model.")
    return _state["model"]


def main():
    parser = argparse.ArgumentParser(description="Run generated model code.")
    parser.add_argument("code", type=Path)
    parser.add_argument("--run-dir", type=Path, default=Path("run"))
    parser.add_argument("--seed", type=int, default=0)
    # threads per workspace (shared/workspaces.py): 1 is fastest for small fully connected models
    parser.add_argument("--threads", type=int, default=WORKSPACE.threads, help="0 = torch default")
    args = parser.parse_args()

    # generated code does "from harness import ..."; make that refer to this module
    sys.modules["harness"] = sys.modules[__name__]
    args.run_dir.mkdir(parents=True, exist_ok=True)
    _state.update(mode="run", run_dir=args.run_dir)
    if args.threads:
        torch.set_num_threads(args.threads)
    torch.manual_seed(args.seed)

    start = time.perf_counter()
    try:
        _exec_student_code(args.code)
    except StudentError as e:
        emit("error", message=str(e))
        sys.exit(1)
    except Exception as e:
        # show only the frames from the student's code, not harness internals
        frames = [f for f in traceback.extract_tb(e.__traceback__) if f.filename == str(args.code)]
        where = f" (line {frames[-1].lineno})" if frames else ""
        emit("error", message=f"{type(e).__name__}{where}: {e}")
        sys.exit(1)
    emit("done", seconds=round(time.perf_counter() - start, 2))


if __name__ == "__main__":
    main()
